WITH ins AS (INSERT INTO match (competition_id, competition_group_id, stage_id, round_label, date, time, best_of, team1_id, team2_id, status, phase, bracket_side) VALUES ((SELECT id FROM competition WHERE source_key = 'leaguepedia:VCS/2021 Season/Winter Season'), NULL, (SELECT id FROM competition_stage WHERE competition_id = (SELECT id FROM competition WHERE source_key = 'leaguepedia:VCS/2021 Season/Winter Season') AND position = 2), 'Demi-finale 2', '2021-12-23', '11:00:00', 'BO5', (SELECT team_id FROM lp_team WHERE lp_name = 'GAM Esports'), (SELECT team_id FROM lp_team WHERE lp_name = 'Burst The Sky Esports'), 'SCHEDULED', 'PLAYOFFS', 'BRACKET') RETURNING id) INSERT INTO lp_match SELECT 'leaguepedia:VCS/2021 Season/Winter Season#2#1', id FROM ins;
WITH ins AS (INSERT INTO match (competition_id, competition_group_id, stage_id, round_label, date, time, best_of, team1_id, team2_id, status, phase, bracket_side) VALUES ((SELECT id FROM competition WHERE source_key = 'leaguepedia:VCS/2021 Season/Winter Season'), NULL, (SELECT id FROM competition_stage WHERE competition_id = (SELECT id FROM competition WHERE source_key = 'leaguepedia:VCS/2021 Season/Winter Season') AND position = 2), 'Petite finale', '2021-12-25', '11:00:00', 'BO5', NULL, NULL, 'SCHEDULED', 'PLAYOFFS', 'PLACEMENT') RETURNING id) INSERT INTO lp_match SELECT 'leaguepedia:VCS/2021 Season/Winter Season#2#2', id FROM ins;
WITH ins AS (INSERT INTO match (competition_id, competition_group_id, stage_id, round_label, date, time, best_of, team1_id, team2_id, status, phase, bracket_side) VALUES ((SELECT id FROM competition WHERE source_key = 'leaguepedia:VCS/2021 Season/Winter Season'), NULL, (SELECT id FROM competition_stage WHERE competition_id = (SELECT id FROM competition WHERE source_key = 'leaguepedia:VCS/2021 Season/Winter Season') AND position = 2), 'Finale', '2021-12-26', '11:00:00', 'BO5', NULL, NULL, 'SCHEDULED', 'PLAYOFFS', 'GRAND_FINAL') RETURNING id) INSERT INTO lp_match SELECT 'leaguepedia:VCS/2021 Season/Winter Season#2#3', id FROM ins;
UPDATE match SET next_match_id = (SELECT match_id FROM lp_match WHERE k = 'leaguepedia:VCS/2021 Season/Winter Season#2#3'), next_match_slot = 1 WHERE id = (SELECT match_id FROM lp_match WHERE k = 'leaguepedia:VCS/2021 Season/Winter Season#2#0');
UPDATE match SET next_match_id = (SELECT match_id FROM lp_match WHERE k = 'leaguepedia:VCS/2021 Season/Winter Season#2#3'), next_match_slot = 2 WHERE id = (SELECT match_id FROM lp_match WHERE k = 'leaguepedia:VCS/2021 Season/Winter Season#2#1');
UPDATE match SET loser_next_match_id = (SELECT match_id FROM lp_match WHERE k = 'leaguepedia:VCS/2021 Season/Winter Season#2#2'), loser_next_match_slot = 1 WHERE id = (SELECT match_id FROM lp_match WHERE k = 'leaguepedia:VCS/2021 Season/Winter Season#2#0');
UPDATE match SET loser_next_match_id = (SELECT match_id FROM lp_match WHERE k = 'leaguepedia:VCS/2021 Season/Winter Season#2#2'), loser_next_match_slot = 2 WHERE id = (SELECT match_id FROM lp_match WHERE k = 'leaguepedia:VCS/2021 Season/Winter Season#2#1');

